   ENGINE.sendPlayerMove(633,286);
};
triggers_mc._visible = false;
block_mc._visible = false;

function randomChoose()
{
   speedTimer = getTimer();
   if(speedTimer - timer >= speed + increaser)
   {
      timer = speedTimer;
      choice = Math.floor(Math.random() * opts);
      trace(choice);
      if(choice == 0)
      {
         if(fish1._currentframe == 1)
         {
            fish1._y = Math.random() * 70 - 20;
         }
         fish1.play();
      }
      else if(choice == 1)
      {
         if(fish2._currentframe == 1)
         {
            fish2._y = Math.random() * 70 - 40;
         }
         fish2.play();
      }
      else if(choice == 2)
      {
         crab1.play();
      }
      else if(choice == 3)
      {
         bubble1.play();
      }
      else if(choice == 4)
      {
         bubble2.play();
      }
      else if(choice == 5)
      {
         bubble3.play();
      }
      else if(choice == 6)
      {
         crab2.play();
      }
      increaser = Math.random() * 10000;
      trace(speed + increaser);
   }
}
timer = getTimer();
speedTimer = getTimer();
speed = 4500;
opts = 7;
increaser = 0;
